describe('Login Spinner Display', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000/login');
  });

  it('should display spinner while async login request is in progress', () => {
    cy.intercept('POST', '/api/login', (req) => {
      req.reply((res) => {
        res.delay(2000);
        res.send({
          statusCode: 200,
          body: { token: 'test-token-123', userId: 'user-1' }
        });
      });
    }).as('loginRequest');

    cy.get('input[name="email"]').type('test@example.com');
    cy.get('input[name="password"]').type('password123');
    cy.get('button[type="submit"]').click();

    cy.get('[data-testid="login-spinner"]').should('be.visible');
    cy.get('[data-testid="login-spinner"]').should('have.class', 'spinner-active');

    cy.wait('@loginRequest');

    cy.get('[data-testid="login-spinner"]').should('not.be.visible');
    cy.url().should('include', '/dashboard');
  });

  it('should hide spinner immediately after successful login response', () => {
    cy.intercept('POST', '/api/login', {
      statusCode: 200,
      body: { token: 'test-token-456', userId: 'user-2' }
    }).as('quickLogin');

    cy.get('input[name="email"]').type('quick@example.com');
    cy.get('input[name="password"]').type('password456');
    cy.get('button[type="submit"]').click();

    cy.get('[data-testid="login-spinner"]').should('be.visible');

    cy.wait('@quickLogin');

    cy.get('[data-testid="login-spinner"]').should('not.exist');
    cy.get('[data-testid="success-message"]').should('contain', 'Login successful');
  });

  it('should display spinner and handle login failure gracefully', () => {
    cy.intercept('POST', '/api/login', (req) => {
      req.reply((res) => {
        res.delay(1500);
        res.send({
          statusCode: 401,
          body: { error: 'Invalid credentials' }
        });
      });
    }).as('failedLogin');

    cy.get('input[name="email"]').type('invalid@example.com');
    cy.get('input[name="password"]').type('wrongpassword');
    cy.get('button[type="submit"]').click();

    cy.get('[data-testid="login-spinner"]').should('be.visible');

    cy.wait('@failedLogin');

    cy.get('[data-testid="login-spinner"]').should('not.be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Invalid credentials');
    cy.url().should('include', '/login');
  });

  it('should prevent multiple simultaneous login requests when spinner is visible', () => {
    cy.intercept('POST', '/api/login', (req) => {
      req.reply((res) => {
        res.delay(3000);
        res.send({
          statusCode: 200,
          body: { token: 'test-token-789', userId: 'user-3' }
        });
      });
    }).as('loginRequest');

    cy.get('input[name="email"]').type('test@example.com');
    cy.get('input[name="password"]').type('password123');
    cy.get('button[type="submit"]').click();

    cy.get('[data-testid="login-spinner"]').should('be.visible');
    cy.get('button[type="submit"]').should('be.disabled');

    cy.get('button[type="submit"]').click({ force: true }).then(() => {
      cy.get('@loginRequest.all').should('have.length', 1);
    });

    cy.wait('@loginRequest');

    cy.get('[data-testid="login-spinner"]').should('not.be.visible');
    cy.get('button[type="submit"]').should('not.be.disabled');
  });

  it('should display spinner with correct accessibility attributes', () => {
    cy.intercept('POST', '/api/login', (req) => {
      req.reply((res) => {
        res.delay(1000);
        res.send({
          statusCode: 200,
          body: { token: 'test-token-101', userId: 'user-4' }
        });
      });
    }).as('loginRequest');

    cy.get('input[name="email"]').type('a11y@example.com');
    cy.get('input[name="password"]').type('password789');
    cy.get('button[type="submit"]').click();

    cy.get('[data-testid="login-spinner"]')
      .should('have.attr', 'role', 'status')
      .should('have.attr', 'aria-live', 'polite')
      .should('have.attr', 'aria-label', 'Loading');

    cy.wait('@loginRequest');

    cy.get('[data-testid="login-spinner"]').should('not.be.visible');
  });
});
